export const Decision = Schema.Struct({
  threadId: Id, blockId: Id, by: ParticipantId, at: Schema.String, decision: Text,
  why: Schema.optionalKey(Text),
})

export const RunStatus = Schema.Literals(['queued', 'running', 'waiting', 'interrupted', 'answered', 'failed', 'stopped'])
export const Run = Schema.Struct({ runId: Id, planId: Id, by: ParticipantId, asked: Text, status: RunStatus, turns: Schema.Int })
export const ToolCall = Schema.Struct({ runId: Id, tool: Schema.String, safeToRepeat: Schema.Boolean })
export const Finding = Schema.Struct({ findingId: Id, explorationId: Id, kind: Schema.Literals(['research', 'spike', 'ask']), summary: Text })
export const Presence = Schema.Struct({ roomId: Id, participant: ParticipantId, focus: Schema.optionalKey(Id) })
